  ('gif-pack:wide-grip-ez-bar-curl', 'Wide-Grip EZ Bar Curl', 'Rosca aberta com barra W', array['upper arms']::text[], array['ez barbell']::text[], array['biceps']::text[], array['forearms']::text[], array['gif-pack/wide-grip-ez-bar-curl.thumb.webp']::text[], 'gif-pack/wide-grip-ez-bar-curl.webp'),
